    def largestTimeFromDigits(self, arr: List[int]) -> str:
        res = ""
        digit_freq = collections.Counter(arr)
        # first digit


        if 2 in arr and sum([digit_freq[d] for d in range(6)]) > 2:
            res += "2"
            arr.remove(2)
        else:
