                    arr.remove(digit)
                    break
            # no 0-3 left in arr
            if len(res) == 1:
                return ""
        # second digit 0-9
        else:
            for digit in range(9,-1,-1):
                if digit in arr:
                    res += str(digit)
                    arr.remove(digit)
                    break

        res += ":"

        for digit in range(5, -1, -1):
            if digit in arr:
                res += str(digit)
                arr.remove(digit)
                break

        if len(res) == 3:
            return ""

        for digit in range(9,-1,-1):
            if digit in arr:
                res += str(digit)
