class Solution:
    def deckRevealedIncreasing(self, deck: List[int]) -> List[int]:
        d = collections.deque()
        deck.sort(reverse=True)
        for i in deck:
            if d:
                d.appendleft(d.pop())
            d.appendleft(i)
        return list(d)
